BEGIN;
PRAGMA writable_schema = on;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '0';
PRAGMA application_id = '0';
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE cotacao_tokens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cotacao_id TEXT,
    token TEXT UNIQUE
);
CREATE TABLE itens (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cotacao_id TEXT,
        medicamento TEXT,
        laboratorio TEXT,
        quantidade INTEGER
    );
CREATE TABLE cotacao_representante (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cotacao_id TEXT,
        representante_id INTEGER,
        status TEXT DEFAULT 'NAO_VISUALIZOU'
    );
CREATE TABLE respostas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cotacao_id TEXT,
    representante_id INTEGER,
    medicamento TEXT,
    preco REAL,
    status TEXT DEFAULT 'NAO_INFORMADO'
, oferta REAL, quantidade_oferta INTEGER);
CREATE TABLE mensagens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cotacao_id TEXT,
    representante_id INTEGER,
    mensagem TEXT,
    data_envio TEXT DEFAULT (datetime('now'))
);
CREATE TABLE itens_pendentes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    medicamento TEXT,
    laboratorio TEXT,
    quantidade INTEGER,
    cotacao_origem TEXT,
    data_registro TEXT DEFAULT (datetime('now'))
);
CREATE TABLE respostas_publicas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cotacao_id TEXT,
    nome TEXT,
    distribuidora TEXT,
    telefone TEXT,
    medicamento TEXT,
    preco REAL,
    status TEXT
);
CREATE TABLE representantes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nome TEXT,
    distribuidora TEXT,
    telefone TEXT,
    email TEXT
);
CREATE TABLE usuarios (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cnpj TEXT UNIQUE,
        email TEXT UNIQUE,
        senha TEXT,
        token_reset TEXT
    , cpf TEXT, ativo INTEGER DEFAULT 0, nome TEXT, remember_token TEXT, token_login TEXT, foto_capa TEXT, foto_perfil TEXT, telefone TEXT, periodo_teste BOOLEAN DEFAULT FALSE, trial_fim TEXT, plano TEXT DEFAULT 'teste');
CREATE TABLE user_activity (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cnpj TEXT,
        last_seen TEXT
    );
CREATE TABLE noticias (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    titulo TEXT,
    resumo TEXT,
    imagem TEXT,
    link TEXT UNIQUE,
    fonte TEXT,
    categoria TEXT,
    data_publicacao TEXT,
    data_importacao TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE respostas_itens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,

    resposta_id INTEGER NOT NULL,

    item_cotacao_id INTEGER NOT NULL,

    possui INTEGER NOT NULL DEFAULT 0,

    valor_unitario REAL,

    valor_oferta REAL,

    quantidade_oferta INTEGER,

    FOREIGN KEY (resposta_id)
    REFERENCES respostas_cotacao(id),

    FOREIGN KEY (item_cotacao_id)
    REFERENCES cotacao_itens(id)
);
CREATE TABLE cotacoes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cnpj_usuario TEXT NOT NULL,
    nome TEXT,
    status TEXT DEFAULT 'RASCUNHO',
    data_criacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE links_cotacao (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cotacao_id INTEGER NOT NULL,
    token TEXT NOT NULL UNIQUE,
    data_criacao TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (cotacao_id) REFERENCES cotacoes(id)
);
CREATE TABLE cotacao_itens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cotacao_id INTEGER NOT NULL,
    medicamento TEXT NOT NULL,
    laboratorio TEXT,
    quantidade INTEGER NOT NULL,
    FOREIGN KEY (cotacao_id) REFERENCES cotacoes(id)
);
CREATE TABLE respostas_cotacao (
    id INTEGER PRIMARY KEY AUTOINCREMENT,

    cotacao_id INTEGER NOT NULL,

    medicamento TEXT NOT NULL,

    representante TEXT NOT NULL,

    distribuidora TEXT,

    whatsapp TEXT,

    status TEXT,

    preco REAL,

    preco_oferta REAL,

    quantidade_oferta INTEGER,

    data_resposta TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    FOREIGN KEY (cotacao_id) REFERENCES cotacoes(id)
);
CREATE TABLE conecta_posts (

    id INTEGER PRIMARY KEY AUTOINCREMENT,

    cnpj TEXT NOT NULL,

    usuario TEXT NOT NULL,

    texto TEXT,

    imagem TEXT,

    data_postagem TIMESTAMP DEFAULT CURRENT_TIMESTAMP

, tipo TEXT DEFAULT 'normal');
CREATE TABLE seguidores (

    id INTEGER PRIMARY KEY AUTOINCREMENT,

    seguidor_cnpj TEXT NOT NULL,

    seguindo_cnpj TEXT NOT NULL,

    data DATETIME DEFAULT CURRENT_TIMESTAMP,

    UNIQUE(seguidor_cnpj, seguindo_cnpj)

);
CREATE TABLE noticias_automaticas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    titulo TEXT NOT NULL,
    link TEXT NOT NULL UNIQUE,
    data_publicacao DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE historico_medicamentos (

        id INTEGER PRIMARY KEY AUTOINCREMENT,

        cnpj_usuario TEXT NOT NULL,

        medicamento TEXT NOT NULL,

        laboratorio TEXT,

        vezes INTEGER DEFAULT 1,

        ultima_data TIMESTAMP DEFAULT CURRENT_TIMESTAMP

    );
