INSERT OR IGNORE INTO 'conecta_posts'('id', 'cnpj', 'usuario', 'texto', 'imagem', 'data_postagem') VALUES (50, 'CotexConecta', 'Cotex Conecta', replace('📰 CFF\n\n    Plenário do CFF aprova atualização das atribuições do farmacêutico nos serviços de saúde\n\n    Clique em "Ler notícia" para acessar a matéria completa.\n    ','\n', char(10)), 'https://admin.cff.org.br/src/uploads/noticia/c41fdda70dade9bf213e7d92f62554c845d2ad04.jpeg', '2026-07-30 21:29:09');
INSERT OR IGNORE INTO 'conecta_posts'('id', 'cnpj', 'usuario', 'texto', 'imagem', 'data_postagem') VALUES (51, 'CotexConecta', 'Cotex Conecta', replace('[FONTE]CFF[/FONTE]\n\n    print(postagem)\n\n    [TITULO]Plenário do CFF aprova atualização das atribuições do farmacêutico nos serviços de saúde[/TITULO]\n\n    [TEXTO]\n    Nova resolução aprovada pelo Plenário reconhece o farmacêutico navegador, amplia competências em regulação, coordenação clínica, telessaúde e navegação do cuidado\n\nO Plenário do Conselho Federal de Farmácia (CFF) aprovou, nesta quinta-feira, 30/07, resolução que atualiza a Resolução CFF nº 730/2022 e amplia as atribuições do farmacêutico nos serviços de saúde.  A norma incorpora competências alinhadas às mais recentes políticas públicas do Sistema Único de Saúde (SUS), fortalecendo a atuação clínica do farmacêutico em áreas estratégicas, como regulação assistencial, navegação do cuidado, transição do cuidado e coordenação clínica.\n\nA proposta foi apresentada pelo conselheiro federal de Farmácia pelo estado do Rio Grande do Sul, Roberto Canquerini, e contou com a contribuição dos membros do\n    [/TEXTO]\n\n    [LINK]https://site.cff.org.br/noticia/Noticias-gerais/30/07/2026/plenario-do-cff-aprova-atualizacao-das-atribuicoes-do-farmaceutico-nos-servicos-de-saude[/LINK]\n    ','\n', char(10)), 'https://admin.cff.org.br/src/uploads/noticia/c41fdda70dade9bf213e7d92f62554c845d2ad04.jpeg', '2026-07-30 21:34:26');
INSERT OR IGNORE INTO 'conecta_posts'('id', 'cnpj', 'usuario', 'texto', 'imagem', 'data_postagem') VALUES (53, 'CotexConecta', 'Cotex Conecta', replace('[FONTE]ANVISA[/FONTE]\n\n    print(postagem)\n\n    [TITULO]Agência Nacional de Vigilância Sanitária - Anvisa[/TITULO]\n\n    [TEXTO]\n    Medicamentos ampliam opções para tratar diabetes e somam o maior volume de aprovações de agonistas de GLP-1 já concedidas pela vigilância sanitária\n\nNovo produto é indicado para melhorar a capacidade de exercício em pacientes adultos\n\nEmpresa detentora do registro do medicamento identificou produto com número de série incompatível\n\nAs medidas proíbem a venda de cateter intravenoso e de curativo fixador para cateter\n\nProduto indicado para tratar febre e dor deve ser recolhido\n    [/TEXTO]\n\n    [LINK]https://www.gov.br/anvisa/pt-br[/LINK]\n    ','\n', char(10)), 'https://www.gov.br/anvisa/logo.png', '2026-07-30 21:38:18');
